// Extracts the conditions the original game consumes ("does the target have X?") from the
// Showdown data shipped with Cobblemon, and writes it as the shared status vocabulary:
//   content/mechanisms/status-vocabulary.ts   tag constants used by producers and consumers
//   build/p5-batch/status-vocabulary.md       appendix for author task cards
//
//   node tools/status-vocabulary.mjs [--check]     --check only verifies the generated files are current
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));
const data = path.join(root, 'build/native-reference/1.8.0+1.21.1/data');
const conditionsFile = path.join(root, 'build/p4-research/locked-showdown/data/conditions.js');
const sources = { moves: 'moves.js', abilities: 'abilities.js', items: 'items.js' };

/** Showdown status codes -> project names (the same names Cobblemon uses for its native statuses). */
const major = { brn: 'burn', par: 'paralysis', slp: 'sleep', frz: 'frozen', psn: 'poison', tox: 'toxic' };
const fieldKinds = { sideCondition: 'side', weather: 'weather', terrain: 'terrain', pseudoWeather: 'pseudoWeather', slotCondition: 'slot' };

function collect(pattern, text, group = 1) {
  return [...text.matchAll(pattern)].map(match => match[group].toLowerCase());
}

const found = { volatile: new Map(), field: {} };
for (const kind of Object.values(fieldKinds)) found.field[kind] = new Map();
function note(map, name, source) { if (!map.has(name)) map.set(name, new Set()); map.get(name).add(source); }

for (const [source, file] of Object.entries(sources)) {
  const text = fs.readFileSync(path.join(data, file), 'utf8');
  for (const name of collect(/(?<![A-Za-z])volatileStatus:\s*['"]([a-z0-9]+)['"]/g, text)) note(found.volatile, name, source);
  for (const name of collect(/\b(?:addVolatile|removeVolatile|getVolatile|hasVolatile)\(['"]([a-z0-9]+)['"]/g, text)) note(found.volatile, name, source);
  for (const name of collect(/volatiles\[['"]([a-z0-9]+)['"]\]/g, text)) note(found.volatile, name, source);
  for (const name of collect(/volatiles\.([a-z0-9]+)/g, text)) note(found.volatile, name, source);
  for (const [key, kind] of Object.entries(fieldKinds))
    for (const name of collect(new RegExp(`(?<![A-Za-z])${key}:\\s*['"]([A-Za-z0-9]+)['"]`, 'g'), text)) note(found.field[kind], name, source);
  for (const code of collect(/(?<![A-Za-z])status:\s*['"]([a-z]+)['"]/g, text)) if (!major[code]) throw Error(`Unknown major status code in ${file}: ${code}`);
}
// conditions.js defines the engine-level conditions (major statuses, weathers and the volatiles the engine itself creates).
const conditions = collect(/^\s{2}([a-z0-9]+):\s*\{/gm, fs.readFileSync(conditionsFile, 'utf8'));
const weatherNames = new Set([...found.field.weather.keys()]);
for (const name of conditions) {
  if (major[name]) continue;
  if (weatherNames.has(name) || ['primordialsea', 'desolateland', 'deltastream'].includes(name)) { note(found.field.weather, name, 'conditions'); continue; }
  note(found.volatile, name, 'conditions');
}

// Engine-only bookkeeping (never referenced by a move, ability or item) is not a state any content consumes.
const volatile = [...found.volatile.keys()].filter(name => ![...found.volatile.get(name)].every(source => source === 'conditions')).sort();
const field = Object.fromEntries(Object.values(fieldKinds).map(kind => [kind, [...found.field[kind].keys()].sort()]));
const majorNames = Object.values(major);

const ts = `/**
 * Generated by tools/status-vocabulary.mjs from the Showdown data shipped with Cobblemon; edit the tool, not this file.
 *
 * Shared identity for combatant states. Consumers ask "does this actor carry the tag" and never depend on a
 * producer's effect id; producers either apply the shared default effect for a name or declare their own
 * variant in startup.ts with \`.tag(StatusVocabulary.tag(name))\`. New concepts can use their own names
 * with the same tag convention; behavior is defined by the content and available implementations.
 */
namespace StatusVocabulary {
    export var namespace = "world_combat";
    /** Names of the shared default major statuses; Cobblemon native ids share these names. */
    export var majorNames: string[] = ${JSON.stringify(majorNames)};
    /** Showdown code -> project name, for reading move/ability data. */
    export var showdownMajor: { [code: string]: string } = ${JSON.stringify(major)};
    /** Volatile conditions consumed anywhere in moves, abilities, items or the engine (${volatile.length}). */
    export var volatile: string[] = ${JSON.stringify(volatile)};
    /** Field-level concepts (not combatant states); shared ids use \`world_combat:field/<name>\` when they become shared. */
    export var field: { [kind: string]: string[] } = ${JSON.stringify(field)};
    export function tag(name: string): string { return namespace + ":status/" + name; }
    export function fieldId(name: string): string { return namespace + ":field/" + name; }
    export function major(name: string): boolean { return majorNames.indexOf(name) >= 0; }
    export function known(name: string): boolean { return major(name) || volatile.indexOf(name) >= 0; }
    /** Vocabulary name embedded in an effect path (\`world_combat:thunderwave_paralysis\` -> \`paralysis\`), or "". */
    export function embedded(effectId: string): string {
        var pathPart = String(effectId).split(":").pop() || "", parts = pathPart.split(/[^a-z0-9]+/);
        for (var i = 0; i < parts.length; i++) if (known(parts[i])) return parts[i];
        return "";
    }
}
`;

function sourcesOf(map, name) { return [...map.get(name)].sort().join('/'); }
const md = `# 状态词表（自动生成）

来源：Cobblemon 自带 Showdown 数据 \`data/moves.js\`、\`abilities.js\`、\`items.js\` 与引擎 \`conditions.js\`；由 \`node tools/status-vocabulary.mjs\` 生成，常量在 \`content/mechanisms/status-vocabulary.ts\`。

词表提供从原作提取的状态命名种子，用于跨内容按 tag 识别状态。已有共享默认效果见下表；其他状态由内容声明 MobEffect 与行为，并用 \`.tag(StatusVocabulary.tag("<名>"))\` 提供身份。新概念同样可以使用自己的名字与这套 tag 约定。具体行为与可调用能力以当前实现为准。

## 主异常的共享默认效果

| 名 | tag | 共享默认效果 | Showdown |
|---|---|---|---|
${majorNames.map(name => {
  const code = Object.keys(major).find(key => major[key] === name);
  const effect = name === 'poison' ? 'minecraft:poison' : name === 'toxic' ? 'minecraft:poison（amplifier ≥ 1）' : `world_combat:${name}`;
  return `| ${name} | \`world_combat:status/${name}\` | \`${effect}\` | ${code} |`;
}).join('\n')}

## 挥发状态（${volatile.length}）

tag 一律 \`world_combat:status/<名>\`；括号内是出现的数据文件。

${volatile.map(name => `\`${name}\`(${sourcesOf(found.volatile, name)})`).join('、')}

## 场地层概念（不是战斗者状态）

以后成为共享定义时 id 用 \`world_combat:field/<名>\`。

${Object.entries(field).map(([kind, names]) => `- ${kind}（${names.length}）：${names.map(name => `\`${name}\``).join('、')}`).join('\n')}
`;

const outputs = [
  [path.join(root, 'content/mechanisms/status-vocabulary.ts'), ts],
  [path.join(root, 'build/p5-batch/status-vocabulary.md'), md]
];
if (process.argv.includes('--check')) {
  for (const [file, text] of outputs) if (!fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== text) { console.error('stale: ' + path.relative(root, file)); process.exitCode = 1; }
  if (!process.exitCode) console.log('status vocabulary current');
} else {
  for (const [file, text] of outputs) fs.writeFileSync(file, text);
  console.log(`status vocabulary: ${majorNames.length} major, ${volatile.length} volatile, ${Object.values(field).flat().length} field concepts`);
}
